import pyopencl as cl
import numpy as np
import itertools
import time

def program_build(kernel_file = 'kernels/row_mulit_matrix.cl'): 
     # Open program file and build
    program_file = open(kernel_file, 'r') # Scale x Matrx
    program_text = program_file.read()
    program = cl.Program(context, program_text)
    try:
        program.build()
    except:
        print("Build log:")
        print(program.get_build_info(devices[0], 
                cl.program_build_info.LOG))
        raise
    return program

def row_mulit_matrix(context, program, row, matrix):
    queue = cl.CommandQueue(context)
    tStart = time.time()#計時開始

    # create buffer READ/WRITE  cl.mem_flags.READ_WRITE
    buffer_row = cl.Buffer(context, cl.mem_flags.READ_WRITE | cl.mem_flags.COPY_HOST_PTR, hostbuf=row)
    buffer_matrix = cl.Buffer(context, cl.mem_flags.READ_WRITE | cl.mem_flags.COPY_HOST_PTR, hostbuf=matrix)
    buffer_result = cl.Buffer(context, cl.mem_flags.WRITE_ONLY,  size = row.nbytes) 
 
    print("matrix.size=", matrix.size)
    event = program.row_mulit_matrix(
                    queue, (matrix.size, ), row.shape,
                    buffer_row, 
                    buffer_matrix,
                    buffer_result)
    event.wait()

    # Read data back from buffer
    result = np.array(row, dtype=np.float32)
    cl.enqueue_copy(queue, result, buffer_result)
    queue.flush()

    tEnd = time.time()#計時結束
    print("It cost %f sec" % (tEnd - tStart))#會自動做近位
    return result
